-- Jordan deep-dive ES/DE/FR translations (completing 267). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Validación centralizada — JoFotara (Sistema Nacional de Facturación Electrónica)', 'Esta página de análisis refleja la orientación pública del ISTD y las noticias del sector disponibles en agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La práctica de aplicación de sanciones y los detalles de incorporación siguen evolucionando — confirme los requisitos vigentes directamente con el Departamento de Impuesto sobre la Renta y las Ventas o con su proveedor de integración antes de basarse en ellos.', 'El despliegue de JoFotara en Jordania ha avanzado por etapas claras desde su lanzamiento voluntario en diciembre de 2022: incorporación obligatoria para los grandes contribuyentes desde enero de 2023, registro universal para todos los contribuyentes registrados a efectos del IVA antes de mayo de 2024, y plena aplicación legal en las transacciones B2B, B2G y B2C desde el 1 de abril de 2025 — con el cierre de un periodo de gracia sancionador para los registros tardíos a finales de mayo de 2025.', 'Las facturas de JoFotara se elaboran en XML y se convierten en JSON cifrado para su transmisión a la plataforma, siguiendo una estructura basada en UBL 2.1. No hay ningún esquema jordano heredado independiente que aprender más allá de esto.', 'JoFotara es un modelo centralizado de Control de Transacciones Continuo (CTC): toda factura debe presentarse a la plataforma y ser validada por ella, en tiempo real o casi real, antes de tener efecto legal o fiscal — esto se aplica de manera uniforme a B2B, B2G y B2C, además del comercio transfronterizo para los contribuyentes residentes, sin exención para pymes ni pequeños negocios.', 'Cumplir significa registrarse con el ISTD, elegir una vía de integración, adaptar el contenido de sus facturas a los campos exigidos por JoFotara, y probar antes de su plazo correspondiente — el portal web gratuito existe precisamente para que los pequeños contribuyentes sin sistemas propios no queden excluidos.', 'Jordania respalda el mandato con sanciones reales y escalonadas: multas fijas por infracción, prisión por incumplimiento persistente y — el verdadero motor de aplicación del mandato — la invalidez absoluta de las facturas no conformes para la deducción del IVA soportado.', 'El sistema de facturación electrónica JoFotara de Jordania ha sido obligatorio para los grandes contribuyentes desde enero de 2023, ampliado a la cobertura universal de contribuyentes registrados a efectos del IVA antes de mayo de 2024, y alcanzó la plena aplicación legal en las transacciones B2B, B2G y B2C el 1 de abril de 2025 — las facturas no transmitidas a través de JoFotara no son válidas para la deducción del IVA, y se aplican multas de JOD 500 o más.', '🇯🇴' FROM countries WHERE name_en = 'Jordan';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Zentralisiertes Clearing — JoFotara (Nationales elektronisches Rechnungssystem)', 'Diese Länderanalyse spiegelt öffentlich verfügbare ISTD-Hinweise und Branchenberichterstattung mit Stand August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Praxis der Bußgeld-Durchsetzung und die Einführungsdetails entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der Einkommen- und Umsatzsteuerbehörde oder Ihrem Integrationsanbieter, bevor Sie sich darauf verlassen.', 'Jordaniens JoFotara-Rollout verlief seit dem freiwilligen Start im Dezember 2022 in klaren Stufen: verpflichtende Einführung für Großsteuerzahler ab Januar 2023, universelle Registrierung für alle umsatzsteuerregistrierten Steuerzahler bis Mai 2024, und vollständige rechtliche Durchsetzung für B2B-, B2G- und B2C-Transaktionen ab dem 1. April 2025 — mit einer Ende Mai 2025 auslaufenden Kulanzfrist für verspätete Registrierungen.', 'JoFotara-Rechnungen werden in XML erstellt und zur Übermittlung an die Plattform in verschlüsseltes JSON umgewandelt, nach einer auf UBL 2.1 basierenden Struktur. Es gibt kein separates altes jordanisches Schema zu lernen, das darüber hinausgeht.', 'JoFotara ist ein zentralisiertes Clearing-Modell mit kontinuierlicher Transaktionskontrolle (CTC): Jede Rechnung muss an die Plattform übermittelt und von ihr validiert werden, in Echtzeit oder nahezu in Echtzeit, bevor sie rechtliche oder steuerliche Wirkung entfaltet — dies gilt einheitlich für B2B, B2G und B2C sowie für grenzüberschreitende Transaktionen gebietsansässiger Steuerzahler, ohne Ausnahme für KMU oder Kleinunternehmen.', 'Compliance bedeutet, sich bei der ISTD zu registrieren, einen Integrationsweg zu wählen, den Rechnungsinhalt den von JoFotara geforderten Feldern zuzuordnen und vor Ihrer jeweiligen Frist zu testen — das kostenlose Webportal existiert genau deshalb, damit kleine Steuerzahler ohne eigene Systeme nicht ausgeschlossen werden.', 'Jordanien untermauert die Pflicht mit echten, eskalierenden Sanktionen: feste Bußgelder pro Verstoß, Freiheitsstrafe bei anhaltender Nichteinhaltung und — der eigentliche Durchsetzungsmotor der Pflicht — die vollständige Ungültigkeit nicht konformer Rechnungen für den Vorsteuerabzug.', 'Jordaniens JoFotara-E-Rechnungssystem ist seit Januar 2023 für Großsteuerzahler verpflichtend, wurde bis Mai 2024 auf eine universelle Abdeckung umsatzsteuerregistrierter Steuerzahler ausgeweitet und erreichte am 1. April 2025 die vollständige rechtliche Durchsetzung für B2B-, B2G- und B2C-Transaktionen — nicht über JoFotara übermittelte Rechnungen sind für den Vorsteuerabzug ungültig, und es gelten Bußgelder von JOD 500 oder mehr.', '🇯🇴' FROM countries WHERE name_en = 'Jordan';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Validation centralisée — JoFotara (Système national de facturation électronique)', 'Cette analyse par pays reflète les orientations publiques de l''ISTD et l''actualité du secteur disponibles en août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La pratique d''application des sanctions et les détails d''intégration continuent d''évoluer — confirmez les exigences actuelles directement auprès du Département des impôts sur le revenu et des ventes ou de votre prestataire d''intégration avant de vous y fier.', 'Le déploiement de JoFotara en Jordanie s''est déroulé par étapes claires depuis son lancement volontaire en décembre 2022 : intégration obligatoire pour les grands contribuables à partir de janvier 2023, enregistrement universel pour tous les contribuables immatriculés à la TVA d''ici mai 2024, et application légale intégrale des transactions B2B, B2G et B2C à partir du 1er avril 2025 — avec la clôture fin mai 2025 d''un délai de grâce pour les enregistrements tardifs.', 'Les factures JoFotara sont rédigées en XML puis converties en JSON chiffré pour transmission à la plateforme, selon une structure fondée sur UBL 2.1. Il n''existe aucun schéma jordanien hérité distinct à apprendre au-delà de cela.', 'JoFotara est un modèle de validation centralisée à contrôle continu des transactions (CTC) : chaque facture doit être soumise à la plateforme et validée par elle, en temps réel ou quasi réel, avant d''avoir un effet légal ou fiscal — cela s''applique uniformément au B2B, au B2G et au B2C, ainsi qu''au commerce transfrontalier pour les contribuables résidents, sans exemption pour les PME ou petites entreprises.', 'Se conformer signifie s''enregistrer auprès de l''ISTD, choisir une méthode d''intégration, faire correspondre le contenu de vos factures aux champs requis par JoFotara, et tester avant votre échéance applicable — le portail web gratuit existe précisément pour que les petits contribuables sans systèmes internes ne soient pas exclus.', 'La Jordanie appuie l''obligation par des sanctions réelles et progressives : amendes fixes par infraction, emprisonnement en cas de non-conformité persistante et — le véritable moteur d''application de l''obligation — l''invalidité pure et simple des factures non conformes pour la déduction de la TVA en amont.', 'Le système de facturation électronique JoFotara de la Jordanie est obligatoire pour les grands contribuables depuis janvier 2023, étendu à une couverture universelle des contribuables immatriculés à la TVA d''ici mai 2024, et a atteint l''application légale intégrale des transactions B2B, B2G et B2C le 1er avril 2025 — les factures non transmises via JoFotara ne sont pas valables pour la déduction de la TVA, et des amendes de 500 JOD ou plus s''appliquent.', '🇯🇴' FROM countries WHERE name_en = 'Jordan';

