INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato de elaboración", "XML, estructura basada en UBL 2.1"], ["Formato de transmisión", "Convertido a JSON cifrado para la API de JoFotara"], ["Artefacto de validación", "Código QR emitido por el ISTD más una referencia única incrustada en la factura validada"], ["Base legal", "Reglamento de Facturación y Control, supervisado por el Departamento de Impuesto sobre la Renta y las Ventas"]]', 'El patrón de elaboración en XML y transmisión en JSON significa que la mayoría de los sistemas de facturación modernos ya producen un formato de partida viable — el verdadero trabajo de integración es la conexión a la API y la adaptación del contenido, no inventar un nuevo tipo de archivo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Erstellungsformat", "XML, auf UBL 2.1 basierende Struktur"], ["Übermittlungsformat", "Für die JoFotara-API in verschlüsseltes JSON umgewandelt"], ["Validierungsartefakt", "Von der ISTD ausgestellter QR-Code plus eine eindeutige Referenz, eingebettet in der validierten Rechnung"], ["Rechtsgrundlage", "Abrechnungs- und Kontrollverordnung, beaufsichtigt von der Einkommen- und Umsatzsteuerbehörde"]]', 'Das Muster aus XML-Erstellung und JSON-Übermittlung bedeutet, dass die meisten modernen Rechnungssysteme bereits ein brauchbares Ausgangsformat erzeugen — die eigentliche Integrationsarbeit ist die API-Anbindung und Inhaltszuordnung, nicht die Erfindung eines neuen Dateityps.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format de rédaction", "XML, structure fondée sur UBL 2.1"], ["Format de transmission", "Converti en JSON chiffré pour l''API JoFotara"], ["Artefact de validation", "Code QR émis par l''ISTD plus une référence unique intégrée dans la facture validée"], ["Base légale", "Règlement sur la facturation et le contrôle, supervisé par le Département des impôts sur le revenu et des ventes"]]', 'Le schéma rédaction-en-XML/transmission-en-JSON signifie que la plupart des systèmes de facturation modernes produisent déjà un format de départ exploitable — le véritable travail d''intégration est la connexion API et la correspondance du contenu, pas l''invention d''un nouveau type de fichier.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de registro fiscal jordano"], ["Vías de acceso", "API directa, el portal web gratuito de JoFotara, o un proveedor de servicios externo certificado"], ["Portal de registro", "portal.jofotara.gov.jo"], ["Panel de reportes", "dashboard.jofotara.gov.jo"]]', 'El portal web gratuito existe precisamente para que la política de no exención para pymes del mandato no deje varados a los pequeños contribuyentes sin software contable — una consideración real dado que Jordania también lo aplica a los profesionales independientes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerzahleridentität", "Jordanische Steuerregistrierungsnummer"], ["Zugangswege", "Direkte API, das kostenlose JoFotara-Webportal oder ein zertifizierter Drittanbieter"], ["Registrierungsportal", "portal.jofotara.gov.jo"], ["Melde-Dashboard", "dashboard.jofotara.gov.jo"]]', 'Das kostenlose Webportal existiert genau deshalb, damit die keine-KMU-Ausnahme-Politik der Pflicht kleine Steuerzahler ohne Buchhaltungssoftware nicht ausschließt — eine reale Erwägung, da Jordanien dies auch auf selbstständige Fachleute anwendet.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identité du contribuable", "Numéro d''enregistrement fiscal jordanien"], ["Voies d''accès", "API directe, portail web gratuit de JoFotara, ou prestataire de services tiers certifié"], ["Portail d''enregistrement", "portal.jofotara.gov.jo"], ["Tableau de bord de déclaration", "dashboard.jofotara.gov.jo"]]', 'Le portail web gratuit existe précisément pour que la politique d''absence d''exemption pour les PME de l''obligation ne laisse pas les petits contribuables sans logiciel comptable démunis — une considération réelle étant donné que la Jordanie l''applique aussi aux professionnels indépendants.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio y archivo', '[["Datos de las partes", "Números de registro fiscal del vendedor y del comprador"], ["Tipos de factura", "Efectivo, por cobrar, ingresos, ventas, ventas especiales, simplificada y de crédito"], ["Umbral de factura simplificada", "Datos del cliente opcionales por debajo de aproximadamente JOD 10.000"], ["Periodo de retención", "4 años, según el Reglamento n.º 34 de 2019"]]', 'El umbral de factura simplificada es una comodidad para las ventas B2C de bajo valor, no una exención — cualquier factura a un comprador registrado a efectos del IVA sigue necesitando el contenido completo de una factura estándar, independientemente del valor.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte & Archivierung', '[["Parteidaten", "Steuerregistrierungsnummern von Verkäufer und Käufer"], ["Rechnungsarten", "Bar-, Forderungs-, Einkommens-, Verkaufs-, Sonderverkaufs-, vereinfachte und Gutschriftsrechnungen"], ["Schwelle für vereinfachte Rechnung", "Kundendaten optional unter etwa JOD 10.000"], ["Aufbewahrungsfrist", "4 Jahre gemäß Verordnung Nr. 34 von 2019"]]', 'Die Schwelle für vereinfachte Rechnungen ist eine Erleichterung für B2C-Verkäufe mit geringem Wert, keine Ausnahme — jede Rechnung an einen umsatzsteuerregistrierten Käufer benötigt weiterhin den vollständigen Inhalt einer Standardrechnung, unabhängig vom Wert.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire et archivage', '[["Données des parties", "Numéros d''enregistrement fiscal du vendeur et de l''acheteur"], ["Types de factures", "Espèces, à recevoir, revenus, ventes, ventes spéciales, simplifiée et note de crédit"], ["Seuil de facture simplifiée", "Coordonnées du client facultatives en dessous d''environ 10 000 JOD"], ["Durée de conservation", "4 ans, selon le règlement n° 34 de 2019"]]', 'Le seuil de facture simplifiée est une commodité pour les ventes B2C de faible valeur, pas une exemption — toute facture à un acheteur immatriculé à la TVA nécessite toujours le contenu complet d''une facture standard, quelle que soit la valeur.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de validación', 'Toda factura de JoFotara pasa por la misma secuencia en tiempo real:', 'Nada llega al cliente hasta que el ISTD la haya validado — esto es lo que hace de JoFotara un verdadero modelo de validación en lugar de un sistema de reporte posterior a la transacción.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Jordan' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Clearing-Ablauf', 'Jede JoFotara-Rechnung durchläuft dieselbe Echtzeit-Sequenz:', 'Nichts erreicht den Kunden, bevor die ISTD es validiert hat — das macht JoFotara zu einem echten Clearing-Modell statt einem Meldesystem nach der Transaktion.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Jordan' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de validation', 'Chaque facture JoFotara suit la même séquence en temps réel :', 'Rien n''atteint le client avant que l''ISTD ne l''ait validé — c''est ce qui fait de JoFotara un véritable modèle de validation plutôt qu''un système de déclaration après transaction.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Jordan' AND lc.sort_order = 0;

