INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Quién está sujeto, y desde cuándo', '[["Grandes contribuyentes", "Obligatorio desde enero de 2023 (Fase 1)"], ["Todos los contribuyentes registrados a efectos del IVA", "Registro obligatorio desde mayo de 2024, plena aplicación desde abril de 2025"], ["Profesionales independientes", "Incluidos — sin exención para consultores, médicos, abogados, etc."], ["Comercio transfronterizo", "Incluido para los contribuyentes residentes"]]', 'Aquí no hay realmente ninguna excepción para pequeñas empresas — Jordania aplica JoFotara al contribuyente registrado más pequeño de la misma manera que al más grande, solo con un plazo más largo para cumplir.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wer betroffen ist, und seit wann', '[["Großsteuerzahler", "Verpflichtend seit Januar 2023 (Phase 1)"], ["Alle umsatzsteuerregistrierten Steuerzahler", "Registrierungspflicht seit Mai 2024, vollständige Durchsetzung seit April 2025"], ["Selbstständige Fachleute", "Eingeschlossen — keine Ausnahme für Berater, Ärzte, Anwälte usw."], ["Grenzüberschreitender Handel", "Für gebietsansässige Steuerzahler eingeschlossen"]]', 'Es gibt hier wirklich keine Ausnahme für Kleinunternehmen — Jordanien wendet JoFotara auf den kleinsten registrierten Steuerzahler genauso an wie auf den größten, nur mit mehr Vorlaufzeit zur Einhaltung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Qui est concerné, et depuis quand', '[["Grands contribuables", "Obligatoire depuis janvier 2023 (Phase 1)"], ["Tous les contribuables immatriculés à la TVA", "Enregistrement obligatoire depuis mai 2024, application intégrale depuis avril 2025"], ["Professionnels indépendants", "Inclus — aucune exemption pour les consultants, médecins, avocats, etc."], ["Commerce transfrontalier", "Inclus pour les contribuables résidents"]]', 'Il n''y a vraiment aucune exception pour les petites entreprises ici — la Jordanie applique JoFotara au plus petit contribuable enregistré de la même manière qu''au plus grand, avec simplement un délai plus long pour se conformer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canales de integración', '[["API directa", "Credenciales emitidas por el ISTD para la integración de sistema a sistema"], ["Portal web", "Gratuito, para empresas sin sistemas de facturación existentes"], ["Proveedores externos", "Proveedores de servicios certificados que ofrecen integración gestionada"]]', 'El diseño de tres vías refleja el enfoque de Egipto y Omán en este rastreador: las empresas de alto volumen se integran directamente, mientras que el portal gratuito evita que los contribuyentes pequeños y de bajo volumen queden excluidos del cumplimiento por coste.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Integrationskanäle', '[["Direkte API", "Von der ISTD ausgestellte Zugangsdaten für die System-zu-System-Integration"], ["Webportal", "Kostenlos, für Unternehmen ohne bestehende Rechnungssysteme"], ["Drittanbieter", "Zertifizierte Dienstleister mit verwalteter Integration"]]', 'Das Drei-Wege-Design spiegelt Ägyptens und Omans Ansatz in diesem Tracker wider: Unternehmen mit hohem Volumen integrieren direkt, während das kostenlose Portal verhindert, dass Kleinunternehmen und Steuerzahler mit geringem Volumen aus Kostengründen von der Compliance ausgeschlossen werden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Canaux d''intégration', '[["API directe", "Identifiants délivrés par l''ISTD pour l''intégration système à système"], ["Portail web", "Gratuit, pour les entreprises sans systèmes de facturation existants"], ["Prestataires tiers", "Prestataires de services certifiés proposant une intégration gérée"]]', 'La conception à trois voies reflète l''approche de l''Égypte et d''Oman dans ce suivi : les entreprises à fort volume s''intègrent directement, tandis que le portail gratuit évite que les contribuables à faible volume et les petites entreprises soient exclus de la conformité pour des raisons de coût.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Incumplimiento inicial', 'Aproximadamente JOD 500 por infracción', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Anfängliche Nichteinhaltung', 'Etwa JOD 500 pro Verstoß', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-conformité initiale', 'Environ 500 JOD par infraction', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Incumplimiento persistente', 'Multas de hasta JOD 1.000, o prisión de 3 a 6 meses, o ambas', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Anhaltende Nichteinhaltung', 'Bußgelder bis zu JOD 1.000, oder Freiheitsstrafe von 3-6 Monaten, oder beides', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-conformité persistante', 'Amendes allant jusqu''à 1 000 JOD, ou emprisonnement de 3 à 6 mois, ou les deux', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Jordan' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Consecuencias en el IVA — el verdadero motor de aplicación', NULL, NULL, 'Una factura no transmitida a través de JoFotara no es válida para la deducción del IVA soportado ni a efectos contables. Un proveedor incumplidor no solo arriesga una multa — sus facturas se vuelven inútiles para sus clientes empresariales registrados a efectos del IVA, lo que impulsa el cumplimiento mucho más eficazmente que las multas por sí solas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Umsatzsteuerliche Folgen — der eigentliche Durchsetzungsmotor', NULL, NULL, 'Eine nicht über JoFotara übermittelte Rechnung ist für den Vorsteuerabzug und buchhalterische Zwecke ungültig. Ein nicht konformer Lieferant riskiert nicht nur ein Bußgeld — seine Rechnungen werden für seine umsatzsteuerregistrierten Geschäftskunden wertlos, was die Compliance weit wirksamer vorantreibt als die Bußgelder allein.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Conséquences en matière de TVA — le véritable moteur d''application', NULL, NULL, 'Une facture non transmise via JoFotara n''est pas valable pour la déduction de la TVA en amont ni à des fins comptables. Un fournisseur non conforme ne risque pas seulement une amende — ses factures deviennent sans valeur pour ses clients professionnels immatriculés à la TVA, ce qui favorise la conformité bien plus efficacement que les amendes seules.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🏛️ Exclusión de contratos gubernamentales', NULL, NULL, 'Las empresas incumplidoras pierden la elegibilidad para licitaciones y contratos del sector público — una consecuencia comercial significativa más allá de la sanción financiera directa para cualquier empresa que venda o quiera vender al gobierno de Jordania.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🏛️ Ausschluss von Regierungsaufträgen', NULL, NULL, 'Nicht konforme Unternehmen verlieren die Berechtigung für öffentliche Ausschreibungen und Aufträge — eine bedeutende geschäftliche Konsequenz über das direkte Bußgeld hinaus für jedes Unternehmen, das an die jordanische Regierung verkauft oder verkaufen möchte.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🏛️ Exclusion des marchés publics', NULL, NULL, 'Les entreprises non conformes perdent leur éligibilité aux appels d''offres et contrats du secteur public — une conséquence commerciale significative au-delà de la sanction financière directe pour toute entreprise qui vend ou souhaite vendre au gouvernement jordanien.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⏰ El periodo de gracia ya ha cerrado', NULL, NULL, 'Existía una exención de las multas acumuladas para las empresas que se registraron antes del 31 de mayo de 2025 — ese periodo de gracia ya está cerrado, por lo que los registros tardíos se enfrentan a la estructura sancionadora completa sin ninguna protección de exención.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⏰ Die Kulanzfrist ist bereits abgelaufen', NULL, NULL, 'Für Unternehmen, die sich vor dem 31. Mai 2025 registrierten, gab es einen Erlass aufgelaufener Bußgelder — diese Kulanzfrist ist nun abgelaufen, sodass verspätete Registrierungen der vollständigen Bußgeldstruktur ohne Erlassschutz gegenüberstehen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⏰ Le délai de grâce est déjà clos', NULL, NULL, 'Une remise des amendes accumulées était disponible pour les entreprises enregistrées avant le 31 mai 2025 — ce délai de grâce est désormais clos, de sorte que les enregistrements tardifs font face à la structure de sanctions complète sans aucune protection de remise.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Jordan' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su estado de registro con el ISTD', 'Toda empresa y profesional independiente registrado a efectos del IVA está sujeto, sin exención — confírmelo directamente con el Departamento de Impuesto sobre la Renta y las Ventas en lugar de suponer que su tamaño o sector lo excluye.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihren Registrierungsstatus bei der ISTD', 'Jedes umsatzsteuerregistrierte Unternehmen und jeder selbstständige Fachmann ist betroffen, ohne Ausnahme — bestätigen Sie dies direkt bei der Einkommen- und Umsatzsteuerbehörde, statt anzunehmen, dass Ihre Größe oder Branche Sie ausschließt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre statut d''enregistrement auprès de l''ISTD', 'Toute entreprise et tout professionnel indépendant immatriculé à la TVA est concerné, sans exemption — confirmez-le directement auprès du Département des impôts sur le revenu et des ventes plutôt que de supposer que votre taille ou votre secteur vous en exclut.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Regístrese en JoFotara si aún no lo ha hecho', 'El periodo de gracia para la exención de multas cerró el 31 de mayo de 2025, por lo que registrarse ahora significa enfrentar la estructura sancionadora completa por cualquier incumplimiento pasado — hágalo con prontitud en lugar de arriesgarse a agravar la exposición.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie sich bei JoFotara, falls noch nicht geschehen', 'Die Kulanzfrist für den Bußgelderlass endete am 31. Mai 2025, sodass eine jetzige Registrierung bedeutet, für vergangene Nichteinhaltung der vollständigen Bußgeldstruktur gegenüberzustehen — handeln Sie zügig, statt das Risiko einer Verschärfung einzugehen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez-vous auprès de JoFotara si ce n''est pas déjà fait', 'Le délai de grâce pour la remise des amendes a pris fin le 31 mai 2025, donc s''enregistrer maintenant signifie faire face à la structure de sanctions complète pour toute non-conformité passée — agissez rapidement plutôt que de risquer d''aggraver l''exposition.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su vía de integración', 'Las empresas de alto volumen deben integrarse mediante API directa; el portal web gratuito conviene a los contribuyentes de bajo volumen y pequeños, y los proveedores externos certificados ofrecen un término medio gestionado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Integrationsweg', 'Unternehmen mit hohem Volumen sollten sich über die direkte API integrieren; das kostenlose Webportal eignet sich für Steuerzahler mit geringem Volumen und Kleinunternehmen, und zertifizierte Drittanbieter bieten einen verwalteten Mittelweg.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre méthode d''intégration', 'Les entreprises à fort volume devraient s''intégrer via une API directe ; le portail web gratuit convient aux contribuables à faible volume et aux petites entreprises, et les prestataires tiers certifiés offrent un compromis géré.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte el contenido de sus facturas a los campos exigidos por JoFotara', 'Cubra cada tipo de factura que emita — efectivo, por cobrar, ingresos, ventas, ventas especiales, simplificada y de crédito — ya que cada uno conlleva sus propias expectativas de campos obligatorios.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihren Rechnungsinhalt den von JoFotara geforderten Feldern zu', 'Decken Sie jede von Ihnen ausgestellte Rechnungsart ab — Bar-, Forderungs-, Einkommens-, Verkaufs-, Sonderverkaufs-, vereinfachte und Gutschriftsrechnungen —, da jede ihre eigenen Pflichtfeld-Anforderungen mit sich bringt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Faites correspondre le contenu de vos factures aux champs requis par JoFotara', 'Couvrez chaque type de facture que vous émettez — espèces, à recevoir, revenus, ventes, ventes spéciales, simplifiée et note de crédit — car chacun comporte ses propres exigences de champs obligatoires.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Enrute todos los canales de venta a través de JoFotara', 'Confirme que el punto de venta, el comercio electrónico y la facturación manual pasen todos por la plataforma antes de confiar en ellos — una factura fuera de JoFotara no tiene efecto legal, sin importar el canal del que provenga.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Leiten Sie jeden Vertriebskanal über JoFotara', 'Stellen Sie sicher, dass POS, E-Commerce und manuelle Rechnungsstellung alle über die Plattform laufen, bevor Sie sich darauf verlassen — eine Rechnung außerhalb von JoFotara hat keine rechtliche Wirkung, unabhängig vom Kanal, aus dem sie stammt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Faites passer chaque canal de vente par JoFotara', 'Vérifiez que le point de vente, le commerce électronique et la facturation manuelle passent tous par la plateforme avant de vous y fier — une facture en dehors de JoFotara n''a aucun effet légal, quel que soit le canal dont elle provient.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Audite las facturas de sus proveedores antes de basarse en ellas para la deducción del IVA', 'Compruebe que exista un código QR y una referencia válidos emitidos por el ISTD antes de tratar la factura de un proveedor como deducible — la carga de cumplimiento va en ambas direcciones.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die Rechnungen Ihrer Lieferanten, bevor Sie sich für den Vorsteuerabzug darauf verlassen', 'Prüfen Sie auf einen gültigen, von der ISTD ausgestellten QR-Code und eine Referenz, bevor Sie die Rechnung eines Lieferanten als abzugsfähig behandeln — die Compliance-Last läuft in beide Richtungen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez les factures de vos fournisseurs avant de vous y fier pour la déduction de la TVA', 'Vérifiez la présence d''un code QR et d''une référence valides émis par l''ISTD avant de considérer la facture d''un fournisseur comme déductible — la charge de conformité s''exerce dans les deux sens.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Jordan' AND ds.sort_order = 5;

